import { randomUUID } from "node:crypto";
import { integer, timestamp, uuid } from "drizzle-orm/pg-core";

/** IDs are generated by the application (not the database) so records can later be created offline. */
export const pk = () => uuid("id").primaryKey().$defaultFn(() => randomUUID());

export const timestamps = () => ({
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow().$onUpdate(() => new Date()),
});

/** Standard columns for organisation-owned records: change tracking + soft delete (sync-ready). */
export const tracked = () => ({
  ...timestamps(),
  version: integer("version").notNull().default(1),
  deletedAt: timestamp("deleted_at", { withTimezone: true }),
});
